// Read the clock, give team 1 a goal, credit the scorer at the current
// minute, give the scorer's AI back, then kick off again from team 0
// (who conceded).
local time = CMND_BTL_GET_MATCH_TIME();
local point = [0, 1];
CMND_BTL_ADD_POINT(point);
CMND_BTL_SET_POINT_HISTORY(1, 1, time / 60, "para_cp0010");
CMND_BTL_STOP_CHARA_AI(false, 1, "para_cp0010");
CMND_BTL_SET_MATCH_RESTART(0);
